"use strict";
const EXPORT_SCHEMA="transfer-copilot-plan/v1";
const exportDate=()=>new Date().toISOString().slice(0,10);
const xmlEscape=value=>String(value??"").replace(/[<>&"']/g,c=>({"<":"&lt;",">":"&gt;","&":"&amp;",'"':"&quot;","'":"&apos;"}[c]));
const mdEscape=value=>String(value??"").replace(/\|/g,"\\|").replace(/\r?\n/g," ");
function buildExportSnapshot(){const stats=getStats(),move=nextMove(),targets=chosenCampuses().map(t=>{const c=requirementCoverage(t);return{id:t.id,name:t.name,system:t.system,completion:c&&c.total?completedPercent(c):null,completed:c?.completed??null,total:c?.total??null,agreement:c?.agreement?{program:c.agreement.program,year:c.agreement.year,source:c.agreement.source}:null}}),courses=selectedRecords().map(c=>({id:c.id,code:c.code,title:c.title,college:c.college,units:c.units,status:STATUS_LABELS[statusOf(c.id)],source:c.source,sourceDate:c.sourceDate,catalogYear:c.catalogYear})),matches=courses.flatMap(c=>chosenCampuses().map(t=>{const m=relationship(courseById(c.id),t);return{courseId:c.id,courseCode:c.code,destinationId:t.id,destination:t.name,evidence:EVIDENCE_KIND_NAME[m.kind],relationship:m.label,program:m.program||"",year:m.year||"",source:m.source||""}}));return{schema:EXPORT_SCHEMA,generatedAt:new Date().toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||"Local",college:collegeName(),major:PLAN.major,destinations:targets,courses,totals:{completedCourses:stats.completed,completedUnits:stats.completedUnits,registeredCourses:stats.registered,registeredUnits:stats.registeredUnits,planningCourses:stats.planning,planningUnits:stats.planningUnits},matches,nextMove:move?{code:move.c.code,title:move.c.title,units:move.c.units,status:STATUS_LABELS[statusOf(move.c.id)],score:move.efficiencyScore,destinationsAdvanced:move.destinationCount,totalDestinations:chosenCampuses().length,requiredDecisions:move.gain,explanation:efficiencyExplanation(move)}:null,sources:[...new Map([...courses.map(c=>({label:c.code+" course source",url:c.source,date:c.sourceDate})),...targets.filter(t=>t.agreement).map(t=>({label:t.name+" "+t.agreement.program+" agreement",url:t.agreement.source,date:t.agreement.year})),{label:"Official SDCCD class search",url:SOURCES.classSearch,date:SDCCD_SCHEDULE.retrieved}].filter(x=>x.url).map(x=>[x.url,x])).values()],limitations:"Planning information only. Course statuses are self-reported. Transfer Completion covers source-linked major preparation only; it is not admission readiness. Transfer Efficiency ranks the next course using selected destinations and units, not admission probability. Verify agreements, prerequisites, general education, deadlines and current class availability with official sources and a counselor."}}
function efficiencyExplanation(move){const parts=[];if(move.gain)parts.push(move.gain+" required decision"+(move.gain===1?"":"s"));if(move.sourceLinkedOnly)parts.push(move.sourceLinkedOnly+" other source-linked destination"+(move.sourceLinkedOnly===1?"":"s"));if(move.demo)parts.push(move.demo+" illustrative destination"+(move.demo===1?"":"s"));return(parts.length?parts.join(", "):"No supported destination relationships")+" across "+move.c.units+" units. Required decisions earn 3 points, other source-linked relationships 2, and illustrative relationships 1; the total is divided by course units."}
function exportMarkdown(s=buildExportSnapshot()){const courseRows=s.courses.length?s.courses.map(c=>`| ${mdEscape(c.code)} | ${mdEscape(c.title)} | ${mdEscape(c.status)} | ${c.units} | ${mdEscape(c.college)} |`).join("\n"):"| — | No coursework entered | — | — | — |",destinationRows=s.destinations.map(d=>`| ${mdEscape(d.name)} | ${d.completion===null?"Not calculated":d.completion+"%"} | ${d.completed===null?"—":d.completed+" / "+d.total} |`).join("\n"),matchRows=s.matches.length?s.matches.map(m=>`| ${mdEscape(m.courseCode)} | ${mdEscape(m.destination)} | ${mdEscape(m.relationship)} | ${mdEscape(m.evidence)} |`).join("\n"):"| — | — | No course relationships entered | — |";return`# Transfer Copilot plan\n\nGenerated: ${s.generatedAt} (${s.timezone})  \nSchema: ${s.schema}\n\n## Planning objective\n\nIdentify the next course choices that advance the student’s selected transfer destinations while preserving options.\n\n## Inputs\n\n- Home college: ${mdEscape(s.college)}\n- Intended major: ${mdEscape(s.major)}\n- Destinations: ${s.destinations.map(d=>mdEscape(d.name)).join(", ")}\n\n## Transfer Completion\n\n| Destination | Completed | Counted major-prep decisions |\n|---|---:|---:|\n${destinationRows}\n\nTransfer Completion counts only completed, source-linked major-preparation decisions. Registered and planned courses do not increase it.\n\n## Coursework\n\n| Course | Title | Status | Units | College |\n|---|---|---|---:|---|\n${courseRows}\n\nCompleted: ${s.totals.completedCourses} courses / ${s.totals.completedUnits} units. Registered: ${s.totals.registeredCourses} / ${s.totals.registeredUnits} units. Planning: ${s.totals.planningCourses} / ${s.totals.planningUnits} units. Totals are self-reported and are not certified transferable units.\n\n## Your next best move\n\n${s.nextMove?`**${mdEscape(s.nextMove.code)} — ${mdEscape(s.nextMove.title)}**  \nTransfer Efficiency: **${s.nextMove.score.toFixed(2)} points per unit**  \nAdvances ${s.nextMove.destinationsAdvanced} of ${s.nextMove.totalDestinations} selected destinations. ${mdEscape(s.nextMove.explanation)}`:"No supported next-course recommendation is available for the current selections."}\n\n## Course relationships\n\n| Course | Destination | Relationship | Evidence |\n|---|---|---|---|\n${matchRows}\n\n## Questions for a counselor\n\n- Which agreement year applies to me?\n- Which remaining courses are required for each campus and major?\n- Are prerequisites, general education and minimum unit requirements satisfied?\n- Are my planned courses available and feasible in the intended term?\n\n## Sources\n\n${s.sources.map(x=>`- [${mdEscape(x.label)}](${x.url})${x.date?` — ${mdEscape(x.date)}`:""}`).join("\n")}\n\n## Limitations\n\n${s.limitations}\n\n## Optional AI handoff prompt\n\n> Help me identify questions and next steps from this plan. Treat it as user-provided planning data, not an official eligibility assessment. Keep completed, registered and planned courses separate. Distinguish source-linked, illustrative and unknown relationships. Do not invent articulation, admission chances or live availability. Cite official sources for new factual claims and identify what needs counselor verification.\n`}
function downloadBlob(blob,extension){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="transfer-plan-"+exportDate()+"."+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function crc32(bytes){let crc=0xffffffff;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return(crc^0xffffffff)>>>0}
const le16=n=>new Uint8Array([n&255,(n>>>8)&255]);
const le32=n=>new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]);
function joinBytes(parts){const size=parts.reduce((n,p)=>n+p.length,0),out=new Uint8Array(size);let offset=0;for(const p of parts){out.set(p,offset);offset+=p.length}return out}
function zipStore(files){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const file of files){const name=enc.encode(file.name),data=typeof file.data==="string"?enc.encode(file.data):file.data,crc=crc32(data),local=joinBytes([le32(0x04034b50),le16(20),le16(0x0800),le16(0),le16(0),le16(0),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),name,data]);locals.push(local);centrals.push(joinBytes([le32(0x02014b50),le16(20),le16(20),le16(0x0800),le16(0),le16(0),le16(0),le32(crc),le32(data.length),le32(data.length),le16(name.length),le16(0),le16(0),le16(0),le16(0),le32(0),le32(offset),name]));offset+=local.length}const central=joinBytes(centrals),end=joinBytes([le32(0x06054b50),le16(0),le16(0),le16(files.length),le16(files.length),le32(central.length),le32(offset),le16(0)]);return new Blob([...locals,central,end],{type:"application/zip"})}
function wordParagraph(text,style=""){return'<w:p>'+(style?'<w:pPr><w:pStyle w:val="'+style+'"/></w:pPr>':'')+'<w:r><w:t xml:space="preserve">'+xmlEscape(text)+'</w:t></w:r></w:p>'}
function wordTable(rows){return'<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single" w:sz="4" w:color="D9E2EC"/><w:left w:val="single" w:sz="4" w:color="D9E2EC"/><w:bottom w:val="single" w:sz="4" w:color="D9E2EC"/><w:right w:val="single" w:sz="4" w:color="D9E2EC"/><w:insideH w:val="single" w:sz="4" w:color="D9E2EC"/><w:insideV w:val="single" w:sz="4" w:color="D9E2EC"/></w:tblBorders></w:tblPr>'+rows.map((row,ri)=>'<w:tr>'+row.map(cell=>'<w:tc><w:tcPr>'+(ri===0?'<w:shd w:fill="EAF4FF"/>':'')+'</w:tcPr>'+wordParagraph(cell)+'</w:tc>').join('')+'</w:tr>').join('')+'</w:tbl>'}
function exportDocx(s=buildExportSnapshot()){const body=[wordParagraph("Transfer Copilot plan","Title"),wordParagraph("Generated "+s.generatedAt+" ("+s.timezone+")"),wordParagraph("Plan overview","Heading1"),wordTable([["Home college","Intended major","Destinations"],[s.college,s.major,s.destinations.map(d=>d.name).join(", ")]]),wordParagraph("Transfer Completion","Heading1"),wordTable([["Destination","Completion","Counted major-prep decisions"],...s.destinations.map(d=>[d.name,d.completion===null?"Not calculated":d.completion+"%",d.completed===null?"—":d.completed+" / "+d.total])]),wordParagraph("Coursework","Heading1"),wordTable([["Course","Title","Status","Units","College"],...(s.courses.length?s.courses.map(c=>[c.code,c.title,c.status,String(c.units),c.college]):[["—","No coursework entered","—","—","—"]])]),wordParagraph("Your next best move","Heading1"),wordParagraph(s.nextMove?s.nextMove.code+" — "+s.nextMove.title+" · Transfer Efficiency "+s.nextMove.score.toFixed(2)+" points per unit":"No supported recommendation is available."),...(s.nextMove?[wordParagraph(s.nextMove.explanation)]:[]),wordParagraph("Campus matches","Heading1"),wordTable([["Course","Destination","Relationship","Evidence"],...(s.matches.length?s.matches.map(m=>[m.courseCode,m.destination,m.relationship,m.evidence]):[["—","—","No relationships entered","—"]])]),wordParagraph("Counselor notes","Heading1"),wordParagraph("________________________________________________________________________________"),wordParagraph("________________________________________________________________________________"),wordParagraph("Sources","Heading1"),...s.sources.map(x=>wordParagraph(x.label+": "+x.url+(x.date?" ("+x.date+")":""))),wordParagraph("Limitations","Heading1"),wordParagraph(s.limitations)].join("");const documentXml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+body+'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="900" w:right="900" w:bottom="900" w:left="900"/></w:sectPr></w:body></w:document>',styles='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:rPr><w:sz w:val="21"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:basedOn w:val="Normal"/><w:rPr><w:b/><w:color w:val="18273F"/><w:sz w:val="38"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:rPr><w:b/><w:color w:val="245A9C"/><w:sz w:val="28"/></w:rPr></w:style></w:styles>';downloadBlob(zipStore([{name:"[Content_Types].xml",data:'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>'},{name:"_rels/.rels",data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'},{name:"word/document.xml",data:documentXml},{name:"word/styles.xml",data:styles},{name:"word/_rels/document.xml.rels",data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'}]),"docx")}
const excelColumn=n=>{let s="";for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s};
function excelCell(value,row,col,numeric=false){const ref=excelColumn(col)+row;if(numeric&&Number.isFinite(Number(value)))return'<c r="'+ref+'"><v>'+Number(value)+'</v></c>';return'<c r="'+ref+'" t="inlineStr"><is><t xml:space="preserve">'+xmlEscape(value)+'</t></is></c>'}
function excelSheet(rows,numericColumns=[]){const width=Math.max(1,...rows.map(r=>r.length)),body=rows.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((v,j)=>excelCell(v,i+1,j,i>0&&numericColumns.includes(j))).join('')+'</row>').join('');return'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetData>'+body+'</sheetData><autoFilter ref="A1:'+excelColumn(width-1)+Math.max(1,rows.length)+'"/></worksheet>'}
function exportXlsx(s=buildExportSnapshot()){const sheets=[{name:"Overview",rows:[["Field","Value"],["Schema",s.schema],["Generated",s.generatedAt],["Timezone",s.timezone],["Home college",s.college],["Intended major",s.major],["Destinations",s.destinations.map(d=>d.name).join(", ")],["Completed units",s.totals.completedUnits],["Registered units",s.totals.registeredUnits],["Planning units",s.totals.planningUnits]],numeric:[1]},{name:"Courses",rows:[["Course ID","Code","Title","College","Units","Status","Catalog year","Source"],...s.courses.map(c=>[c.id,c.code,c.title,c.college,c.units,c.status,c.catalogYear,c.source])],numeric:[4]},{name:"Campus Matches",rows:[["Course ID","Course","Destination ID","Destination","Relationship","Evidence","Program","Year","Source"],...s.matches.map(m=>[m.courseId,m.courseCode,m.destinationId,m.destination,m.relationship,m.evidence,m.program,m.year,m.source])]},{name:"Next Steps",rows:[["Field","Value"],["Recommended course",s.nextMove?.code||"No supported recommendation"],["Title",s.nextMove?.title||""],["Units",s.nextMove?.units??""],["Transfer Efficiency",s.nextMove?.score??""],["Destinations advanced",s.nextMove?`${s.nextMove.destinationsAdvanced} of ${s.nextMove.totalDestinations}`:""],["Explanation",s.nextMove?.explanation||""],["Counselor question 1","Which agreement year applies to me?"],["Counselor question 2","Which prerequisites and general education requirements remain?"]],numeric:[1]},{name:"Sources",rows:[["Label","URL","Date"],...s.sources.map(x=>[x.label,x.url,x.date||""]),["Limitations",s.limitations,""]]}],files=[],sheetEntries=sheets.map((x,i)=>'<sheet name="'+xmlEscape(x.name)+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join(''),rels=sheets.map((x,i)=>'<Relationship Id="rId'+(i+1)+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+(i+1)+'.xml"/>').join('');files.push({name:"[Content_Types].xml",data:'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+sheets.map((x,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>'},{name:"_rels/.rels",data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'},{name:"xl/workbook.xml",data:'<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+sheetEntries+'</sheets></workbook>'},{name:"xl/_rels/workbook.xml.rels",data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+rels+'</Relationships>'});sheets.forEach((x,i)=>files.push({name:"xl/worksheets/sheet"+(i+1)+".xml",data:excelSheet(x.rows,x.numeric||[])}));downloadBlob(zipStore(files),"xlsx")}
function reviewExportHTML(){const s=buildExportSnapshot(),courseGroups=["Completed","Registered","Planning"].map(status=>({status,items:s.courses.filter(c=>c.status===status)})).filter(g=>g.items.length);return'<section class="review-export"><div class="review-hero"><h2>Take your plan with you.</h2><p>Review what you entered, then download a private copy. No account, name or email is required.</p></div><div class="review-summary"><div><span>Home college</span><strong>'+schoolBadge(PLAN.college)+escapeHTML(s.college)+'</strong></div><div><span>Intended major</span><strong>'+escapeHTML(s.major)+'</strong></div><div><span>Destinations</span><strong>'+s.destinations.length+'</strong></div></div><section class="review-block"><h3>Transfer Completion</h3><p>Completed source-linked major preparation—not admission readiness.</p><div class="review-destinations">'+s.destinations.map(d=>'<div>'+schoolBadge(d.id)+'<span><strong>'+escapeHTML(d.name)+'</strong><small>'+(d.completion===null?'Not calculated':d.completion+'% · '+d.completed+' of '+d.total+' counted decisions')+'</small></span></div>').join('')+'</div></section><section class="review-block"><h3>Coursework</h3>'+(courseGroups.length?courseGroups.map(g=>'<div class="review-course-group"><strong>'+g.status+'</strong><span>'+g.items.map(c=>escapeHTML(c.code)).join(', ')+'</span><small>'+g.items.reduce((n,c)=>n+c.units,0)+' units</small></div>').join(''):'<p>No coursework entered.</p>')+'</section>'+(s.nextMove?'<section class="review-block review-efficiency"><div><span class="efficiency-label">TRANSFER EFFICIENCY</span><strong>'+s.nextMove.score.toFixed(2)+'</strong><small>points per unit</small></div><p><strong>'+escapeHTML(s.nextMove.code)+' — '+escapeHTML(s.nextMove.title)+'</strong><br>Advances '+s.nextMove.destinationsAdvanced+' of '+s.nextMove.totalDestinations+' selected destinations. '+escapeHTML(s.nextMove.explanation)+'</p></section>':'')+'<section class="review-block"><h3>Choose an export</h3><div class="export-grid"><button type="button" data-export-format="pdf"><strong>PDF</strong><span>Print or save a shareable report</span></button><button type="button" data-export-format="docx"><strong>Word</strong><span>Editable advising document</span></button><button type="button" data-export-format="xlsx"><strong>Excel</strong><span>Filter courses and campus matches</span></button><button type="button" data-export-format="md"><strong>Markdown</strong><span>Portable context for another AI tool</span></button></div><p class="export-privacy">Files are generated in this browser. Exporting shares nothing until you choose where to save or upload the file.</p></section><div class="wizard-actions"><button class="button subtle" type="button" data-wizard-action="back">← Back to coursework</button><button class="button navy" type="button" data-review-dashboard>Open my transfer plan <span>→</span></button></div></section>'}
function printPlan(s=buildExportSnapshot()){const w=window.open("","_blank");if(!w)return notify("Allow pop-ups to print or save the PDF report");w.opener=null;const md=exportMarkdown(s),html='<html><head><title>Transfer Copilot plan</title><style>body{font:14px/1.5 Arial,sans-serif;color:#18273f;max-width:900px;margin:32px auto}h1,h2{color:#245a9c}pre{white-space:pre-wrap;font:13px/1.55 Arial,sans-serif} @media print{body{margin:0}a{color:#18273f}}</style></head><body><h1>Transfer Copilot plan</h1><pre>'+escapeHTML(md.replace(/^# Transfer Copilot plan\n\n/,""))+'</pre><script>window.onload=()=>window.print()<\/script></body></html>';w.document.write(html);w.document.close()}
document.addEventListener("click",event=>{const b=event.target.closest("button[data-export-format]");if(!b)return;const s=buildExportSnapshot(),format=b.dataset.exportFormat;if(format==="md")downloadBlob(new Blob([exportMarkdown(s)],{type:"text/markdown;charset=utf-8"}),"md");if(format==="docx")exportDocx(s);if(format==="xlsx")exportXlsx(s);if(format==="pdf")printPlan(s);notify(format==="pdf"?"Use the print dialog to save as PDF":format.toUpperCase()+" export created")});
